"""Baseline: measured outline extruded, holes cut. Generated by baseline_cad.py."""
import cadquery as cq


def build_part(
    thickness=3.0,
    corner1_u=-53.32, corner1_v=-48.4,
    corner2_u=-52.67, corner2_v=47.93,
    corner3_u=38.06, corner3_v=46.03,
    corner4_u=53.13, corner4_v=33.84,
    corner5_u=53.27, corner5_v=-47.45,
    hole1_u=-41.8, hole1_v=38.41, hole1_diameter=6.15,
    hole2_u=-40.5, hole2_v=-38.2, hole2_diameter=6.09,
    hole3_u=37.52, hole3_v=36.67, hole3_diameter=5.95,
    hole4_u=38.54, hole4_v=-37.7, hole4_diameter=5.85,
):
    part = cq.Workplane("XY").polyline([(corner1_u, corner1_v), (corner2_u, corner2_v), (corner3_u, corner3_v), (corner4_u, corner4_v), (corner5_u, corner5_v)]).close().extrude(thickness)
    part = part.cut(cq.Workplane("XY", origin=(hole1_u, hole1_v, -1)).circle(hole1_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole2_u, hole2_v, -1)).circle(hole2_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole3_u, hole3_v, -1)).circle(hole3_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole4_u, hole4_v, -1)).circle(hole4_diameter / 2).extrude(thickness + 2))
    return part
